dir:
























































	select 1 as id

	select *, 0*tien_nt as da_pb_nt, 0*tien_nt as cl_nt into #v from ctchi20 
	update #v set da_pb_nt = b.tt_nt from #v a join (select ma_kh, ma_nt, id, sum(tt_nt) as tt_nt from ctct20 where loai_tt = 1 and id in (select id from #v) group by ma_kh, ma_nt, id) b on a.id = b.id and a.ma_kh = b.ma_kh and a.ma_nt = b.ma_nt
	update #v set cl_nt=tien_nt-da_pb_nt

	select a.id id_dh, a.ma_kh, b.ten_kh, a.tien_nt t_tien2, a.tien, a.dien_giai, a.ma_bp, a.da_pb_nt, cl_nt t_tien, cl_nt t_tt from #v a left join dmkh b on a.ma_kh = b.ma_kh where a.id = @so_ct

	drop table #v









  &DefaultButton;




function filter$m65ctchi20Select(p){
  this.constructor(p);
}
filter$m65ctchi20Select.prototype = new DirEvent();
filter$m65ctchi20Select.prototype.beforeInit = function(){
  var p = this._dir;

}


filter$m65ctchi20Select.prototype.afterInit = function(){
	var p = this._dir,g = p.grid(0),master = g.ds.get(1), rErr = '';
  p.valForm(['ngay_ct1','ngay_ct2','id', 'ma_noi_di', 'ten_noi_di', 'ma_noi_den', 'ten_noi_den', 'ma_nt', 'unit_id'], [p.options._ngay_ct1,p.options._ngay_ct2,p.options._so_ct,p.options._ma_noi_di, p.options._ten_noi_di,p.options._ma_noi_den, p.options._ten_noi_den,  p.options._ma_nt, p.options._unit_id]);
	dir$m65ctchi20SetMaster(p);

}

function dir$m65ctchi20SetMaster(p) {
  p.request('ma_kh_request', '', ['id']);
}

filter$m65ctchi20Select.prototype.beforeAcceptFilter = function (m2, opt, sub) {
  var p = this._dir, pa = p.options.parent, g = p.grid(), dt = g.data, master = g.ds.get(1), rErr = '';

 var fun = function(){
	//dt.removeRow('[so_luong] == 0');
    //pa.appendGrid(0, dt, p.valForm('xprocess') == "2", 'so_luong', 'so_luong');
	//pa.calcExpressionAll(0, 'so_luong');
    pa.appendForm(master, 0);
    p._close();
  }

  if (rErr.length) {
    $.question('$VoucherRetrieveLimit', null, p, function(q, v){
      q._close();
      if (v) fun();
    });
  } else fun();


  //p._close();

  return false;
}






