				  	select *, 0*tien_nt as da_pb_nt, 0*tien_nt as cl_nt into #v from ctchi20 
					update #v set da_pb_nt = b.tt_nt from #v a join (select ma_kh, ma_nt, id, sum(tt_nt) as tt_nt from ctct20 where loai_tt = 1 and id in (select id from #v) group by ma_kh, ma_nt, id) b on a.id = b.id and a.ma_kh = b.ma_kh and a.ma_nt = b.ma_nt
					update #v set cl_nt=tien_nt-da_pb_nt

